function Test-StringArrayEqual([string[]]$Left, [string[]]$Right) {
    if ($Left.Count -ne $Right.Count) { return $false }
    for ($index = 0; $index -lt $Left.Count; $index++) { if ($Left[$index] -cne $Right[$index]) { return $false } }
