function Assert-ExternalWriteBlocked([string]$Path) {
    try { Add-Content -LiteralPath $Path -Value ' external mutation'; throw "Write was not blocked: $Path" }
    catch [IO.IOException] { return }
    finally { }
}
function Assert-ExternalReplaceBlocked([string]$Path) {
    $replacement = Join-Path ([IO.Path]::GetDirectoryName($Path)) ('.l00c-replace-' + [Guid]::NewGuid().ToString('N') + '.tmp')
    $backup = $replacement + '.backup'
    try {
        [IO.File]::WriteAllText($replacement, 'external replacement', [Text.UTF8Encoding]::new($false))
        try { [IO.File]::Replace($replacement, $Path, $backup, $true); throw "Replace was not blocked: $Path" }
        catch [IO.IOException] { return }
    }
    finally { foreach ($temporary in @($replacement, $backup)) { if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force } } }
}
function Assert-ExternalMutationBlocked([string]$Path) {
